"""Inventário de software via SNMP (HOST-RESOURCES-MIB) e WMI."""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import UTC, datetime
import logging

from app.config import settings
from app.engines.discovery.snmp_collector import _snmp_walk
from app.engines.discovery.wmi_collector import _wmi_query, wmi_credentials_configured

logger = logging.getLogger(__name__)

HR_SW_INSTALLED_NAME = "1.3.6.1.2.1.25.6.3.1.2"
HR_SW_INSTALLED_ID = "1.3.6.1.2.1.25.6.3.1.3"


@dataclass
class SoftwarePackage:
    name: str
    version: str | None = None
    vendor: str | None = None
    source: str = "snmp"

    def to_dict(self) -> dict:
        return {
            "name": self.name,
            "version": self.version,
            "vendor": self.vendor,
            "source": self.source,
        }


@dataclass
class SoftwareInventory:
    packages: list[SoftwarePackage] = field(default_factory=list)
    sources: list[str] = field(default_factory=list)
    collected_at: str | None = None
    error: str | None = None

    def to_extra_data(self) -> dict:
        return {
            "software": {
                "packages": [p.to_dict() for p in self.packages],
                "sources": self.sources,
                "collected_at": self.collected_at,
                "count": len(self.packages),
                "error": self.error,
            }
        }


def collect_software_snmp(
    host: str,
    community: str | None = None,
    *,
    limit: int | None = None,
) -> list[SoftwarePackage]:
    limit = limit or settings.software_inventory_max_packages
    names = _snmp_walk(host, HR_SW_INSTALLED_NAME, community, limit=limit)
    if not names:
        return []

    ids = _snmp_walk(host, HR_SW_INSTALLED_ID, community, limit=limit)
    packages: list[SoftwarePackage] = []
    for index, raw_name in enumerate(names):
        name = raw_name.strip()
        if not name or name.lower() in ("null", ""):
            continue
        version = ids[index].strip() if index < len(ids) else None
        if version and version.lower() == "null":
            version = None
        packages.append(SoftwarePackage(name=name, version=version, source="snmp"))
    return packages


def collect_software_wmi(
    host: str,
    username: str | None = None,
    password: str | None = None,
    domain: str | None = None,
    *,
    limit: int | None = None,
    include_slow_product_query: bool = False,
) -> list[SoftwarePackage]:
    if not wmi_credentials_configured() and not (username and password):
        return []

    limit = limit or settings.software_inventory_max_packages
    username = username or settings.wmi_username
    password = password or settings.wmi_password
    domain = domain if domain is not None else settings.wmi_domain
    timeout = settings.wmi_timeout_seconds
    packages: list[SoftwarePackage] = []

    try:
        store_rows = _wmi_query(
            host,
            username,
            password,
            domain,
            "SELECT Name, Version, Vendor FROM Win32_InstalledStoreProgram",
            timeout,
        )
        for row in store_rows[:limit]:
            name = row.get("Name", "").strip()
            if name:
                packages.append(
                    SoftwarePackage(
                        name=name,
                        version=row.get("Version") or None,
                        vendor=row.get("Vendor") or None,
                        source="wmi",
                    )
                )

        patch_rows = _wmi_query(
            host,
            username,
            password,
            domain,
            "SELECT Caption, Description, HotFixID FROM Win32_QuickFixEngineering",
            min(timeout, 10.0),
        )
        for row in patch_rows:
            if len(packages) >= limit:
                break
            caption = row.get("Caption") or row.get("HotFixID") or row.get("Description")
            if caption:
                packages.append(
                    SoftwarePackage(
                        name=caption.strip(),
                        version=row.get("HotFixID") or None,
                        vendor="Microsoft",
                        source="wmi",
                    )
                )

        if include_slow_product_query and len(packages) < limit:
            product_rows = _wmi_query(
                host,
                username,
                password,
                domain,
                "SELECT Name, Version, Vendor FROM Win32_Product",
                min(timeout * 2, 30.0),
            )
            for row in product_rows:
                if len(packages) >= limit:
                    break
                name = row.get("Name", "").strip()
                if name:
                    packages.append(
                        SoftwarePackage(
                            name=name,
                            version=row.get("Version") or None,
                            vendor=row.get("Vendor") or None,
                            source="wmi",
                        )
                    )
    except ImportError:
        logger.warning("impacket não instalado — inventário WMI indisponível")
    except Exception as exc:
        logger.debug("WMI software collection failed for %s: %s", host, exc)

    return packages[:limit]


def collect_device_software(
    host: str,
    *,
    use_snmp: bool = True,
    use_wmi: bool = True,
    snmp_community: str | None = None,
    include_slow_wmi: bool = False,
) -> SoftwareInventory:
    inventory = SoftwareInventory(collected_at=datetime.now(UTC).isoformat())
    seen: set[str] = set()

    if use_snmp:
        try:
            for pkg in collect_software_snmp(host, snmp_community):
                key = pkg.name.lower()
                if key not in seen:
                    seen.add(key)
                    inventory.packages.append(pkg)
            if any(p.source == "snmp" for p in inventory.packages):
                inventory.sources.append("snmp")
        except Exception as exc:
            inventory.error = f"SNMP: {exc}"

    if use_wmi and wmi_credentials_configured():
        try:
            for pkg in collect_software_wmi(host, include_slow_product_query=include_slow_wmi):
                key = pkg.name.lower()
                if key not in seen:
                    seen.add(key)
                    inventory.packages.append(pkg)
            if any(p.source == "wmi" for p in inventory.packages):
                if "wmi" not in inventory.sources:
                    inventory.sources.append("wmi")
        except Exception as exc:
            err = f"WMI: {exc}"
            inventory.error = f"{inventory.error}; {err}" if inventory.error else err

    return inventory

import ipaddress
import socket


def reverse_dns(ip: str, timeout: float = 2.0) -> str | None:
    original_timeout = socket.getdefaulttimeout()
    try:
        socket.setdefaulttimeout(timeout)
        hostname, _, _ = socket.gethostbyaddr(ip)
        return hostname
    except (socket.herror, socket.gaierror, OSError):
        return None
    finally:
        socket.setdefaulttimeout(original_timeout)


def validate_subnet(cidr: str) -> ipaddress.IPv4Network | ipaddress.IPv6Network:
    network = ipaddress.ip_network(cidr, strict=False)
    if network.num_addresses > 4096:
        raise ValueError("Sub-rede muito grande. Máximo permitido: /20 (4096 endereços)")
    return network


def iter_host_addresses(cidr: str) -> list[str]:
    network = validate_subnet(cidr)
    if network.version == 4:
        return [str(ip) for ip in network.hosts()]
    return [str(ip) for ip in network.hosts()]

"""Cálculo de progresso do scan: 0–5% nmap, 5–99% inventário por host."""

NMAP_MAX_PERCENT = 5
INVENTORY_MAX_PERCENT = 99


def nmap_percent(ratio: float) -> int:
    """ratio 0.0–1.0 dentro da fase nmap → 0–5%."""
    return min(NMAP_MAX_PERCENT, max(0, int(NMAP_MAX_PERCENT * min(1.0, ratio))))


def nmap_range_percent(start_ratio: float, end_ratio: float, inner_ratio: float) -> int:
    """Interpola dentro de um sub-intervalo da fase nmap (0–5%)."""
    lo = nmap_percent(start_ratio)
    hi = nmap_percent(end_ratio)
    span = max(hi - lo, 1)
    return lo + int(span * min(1.0, max(0.0, inner_ratio)))


def inventory_percent(hosts_done: float, total: int) -> int:
    """hosts_done pode ser fracionário (heartbeat) · total = hosts a inventariar."""
    if total <= 0:
        return NMAP_MAX_PERCENT
    ratio = min(1.0, max(0.0, hosts_done / total))
    span = INVENTORY_MAX_PERCENT - NMAP_MAX_PERCENT
    return min(INVENTORY_MAX_PERCENT, NMAP_MAX_PERCENT + int(span * ratio))

from icmplib import async_ping

from app.config import settings


async def ping_host(host: str, timeout: int | None = None) -> tuple[bool, float | None]:
    timeout = timeout or settings.ping_timeout_seconds
    try:
        result = await async_ping(host, count=1, timeout=timeout, privileged=False)
        if result.is_alive:
            return True, round(result.avg_rtt, 2)
        return False, None
    except Exception:
        return False, None

import asyncio
import time


async def check_tcp(host_port: str, timeout: int = 3) -> tuple[bool, float]:
    if ":" in host_port:
        host, port_str = host_port.rsplit(":", 1)
        port = int(port_str)
    else:
        host, port = host_port, 80

    start = time.perf_counter()
    try:
        _, writer = await asyncio.wait_for(asyncio.open_connection(host, port), timeout=timeout)
        writer.close()
        await writer.wait_closed()
        return True, round((time.perf_counter() - start) * 1000, 2)
    except Exception:
        return False, round((time.perf_counter() - start) * 1000, 2)

"""SSE de monitoramento — não bloqueia shutdown do uvicorn."""

from __future__ import annotations

import asyncio
import json
import time

from fastapi import APIRouter, HTTPException, Query, Request
from fastapi.responses import StreamingResponse
from jose import JWTError, jwt

from app.dependencies import ALGORITHM
from app.config import settings
from app.services.realtime_events import event_bus

router = APIRouter()

# Evita conexões eternas a segurar o reload do --reload
SSE_MAX_SECONDS = 300


def _username_from_token(token: str) -> str | None:
    try:
        payload = jwt.decode(token, settings.secret_key, algorithms=[ALGORITHM])
        return payload.get("sub")
    except JWTError:
        return None


@router.get("/monitoring")
async def monitoring_stream(request: Request, token: str = Query(...)):
    """SSE de eventos de monitoramento, discovery e status."""
    if not _username_from_token(token):
        raise HTTPException(status_code=401, detail="Token inválido")

    async def generate():
        queue = await event_bus.subscribe()
        started = time.monotonic()
        try:
            for item in event_bus.recent(5):
                if await request.is_disconnected():
                    break
                yield f"data: {json.dumps(item)}\n\n"
            while True:
                if await request.is_disconnected():
                    break
                if time.monotonic() - started > SSE_MAX_SECONDS:
                    yield f"data: {json.dumps({'type': 'reconnect', 'payload': {}, 'created_at': ''})}\n\n"
                    break
                try:
                    event = await asyncio.wait_for(queue.get(), timeout=10.0)
                    yield f"data: {json.dumps(event.to_dict())}\n\n"
                except asyncio.TimeoutError:
                    yield f"data: {json.dumps({'type': 'heartbeat', 'payload': {}, 'created_at': ''})}\n\n"
                    await asyncio.sleep(0)
        except asyncio.CancelledError:
            raise
        finally:
            event_bus.unsubscribe(queue)

    return StreamingResponse(
        generate(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "Connection": "keep-alive",
            "X-Accel-Buffering": "no",
        },
    )

"""Event bus in-memory para SSE / push de monitoramento."""

from __future__ import annotations

import asyncio
from collections import deque
from dataclasses import dataclass, field
from datetime import UTC, datetime
from typing import Any

MAX_EVENTS = 500


@dataclass
class RealtimeEvent:
    type: str
    payload: dict[str, Any] = field(default_factory=dict)
    created_at: str = field(default_factory=lambda: datetime.now(UTC).isoformat())

    def to_dict(self) -> dict[str, Any]:
        return {"type": self.type, "payload": self.payload, "created_at": self.created_at}


class RealtimeEventBus:
    def __init__(self) -> None:
        self._history: deque[RealtimeEvent] = deque(maxlen=MAX_EVENTS)
        self._subscribers: set[asyncio.Queue[RealtimeEvent]] = set()

    def publish(self, event_type: str, payload: dict[str, Any] | None = None) -> None:
        event = RealtimeEvent(type=event_type, payload=payload or {})
        self._history.append(event)
        for queue in list(self._subscribers):
            try:
                queue.put_nowait(event)
            except asyncio.QueueFull:
                pass

    def recent(self, limit: int = 20) -> list[dict[str, Any]]:
        return [e.to_dict() for e in list(self._history)[-limit:]]

    async def subscribe(self) -> asyncio.Queue[RealtimeEvent]:
        queue: asyncio.Queue[RealtimeEvent] = asyncio.Queue(maxsize=64)
        self._subscribers.add(queue)
        return queue

    def unsubscribe(self, queue: asyncio.Queue[RealtimeEvent]) -> None:
        self._subscribers.discard(queue)


event_bus = RealtimeEventBus()

import hashlib
import re
from datetime import UTC, datetime

from sqlalchemy import text
from sqlalchemy.orm import Session

from app.models import Device, LinkTraffic


def _normalize_port(name: str | None) -> str:
    if not name:
        return ""
    return re.sub(r"[^a-z0-9]", "", name.lower())


def _match_interface(interfaces: list[dict], port_name: str | None) -> dict | None:
    if not port_name or not interfaces:
        return None
    target = _normalize_port(port_name)
    for iface in interfaces:
        if _normalize_port(iface.get("name")) == target:
            return iface
    for iface in interfaces:
        iname = _normalize_port(iface.get("name"))
        if target and (target in iname or iname in target):
            return iface
    return None


def _compute_bps(current_octets: int, previous_octets: int, elapsed_seconds: float) -> float:
    if elapsed_seconds <= 0:
        return 0.0
    delta = current_octets - previous_octets
    if delta < 0:
        delta = current_octets
    return max(0.0, (delta * 8) / elapsed_seconds)


def update_device_interface_counters(device: Device, interfaces: list[dict]) -> None:
    extra = dict(device.extra_data or {})
    prev_interfaces = {i.get("index"): i for i in (extra.get("interfaces") or []) if isinstance(i, dict)}
    now = datetime.now(UTC)
    enriched: list[dict] = []

    for iface in interfaces:
        idx = iface.get("index")
        prev = prev_interfaces.get(idx, {})
        prev_sample = prev.get("sampled_at")
        elapsed = 60.0
        if prev_sample:
            try:
                prev_dt = datetime.fromisoformat(prev_sample.replace("Z", "+00:00"))
                elapsed = max(1.0, (now - prev_dt).total_seconds())
            except ValueError:
                pass

        in_bps = _compute_bps(iface.get("in_octets", 0), prev.get("in_octets", 0), elapsed)
        out_bps = _compute_bps(iface.get("out_octets", 0), prev.get("out_octets", 0), elapsed)
        speed = iface.get("speed_bps") or 0
        util = round((max(in_bps, out_bps) / speed) * 100, 1) if speed > 0 else None

        enriched.append(
            {
                **iface,
                "in_bps": round(in_bps, 1),
                "out_bps": round(out_bps, 1),
                "util_pct": util,
                "sampled_at": now.isoformat(),
            }
        )

    extra["interfaces"] = enriched
    device.extra_data = extra


def sync_link_traffic(session: Session) -> int:
    link_ids = session.execute(
        text("SELECT id, source_device_id, source_port FROM network_links WHERE lower(protocol::text) = 'manual'")
    ).all()
    updated = 0

    for link_id, source_device_id, source_port in link_ids:
        source = session.get(Device, source_device_id)
        if not source:
            continue

        interfaces = (source.extra_data or {}).get("interfaces") or []
        iface = _match_interface(interfaces, source_port)
        bps_in = bps_out = util_pct = None
        source_type = "simulated"

        if iface:
            bps_in = float(iface.get("in_bps") or 0)
            bps_out = float(iface.get("out_bps") or 0)
            util_pct = iface.get("util_pct")
            source_type = "snmp"
        else:
            simulated = _simulated_traffic(link_id)
            bps_out = simulated["bps_out"]
            bps_in = simulated["bps_in"]
            util_pct = simulated["util_pct"]
            source_type = "simulated"

        if bps_in is None:
            continue

        row = session.get(LinkTraffic, link_id)
        if not row:
            row = LinkTraffic(link_id=link_id)
        row.bps_in = bps_in
        row.bps_out = bps_out
        row.util_pct = util_pct
        row.source = source_type
        row.updated_at = datetime.now(UTC)
        session.add(row)
        updated += 1

    return updated


def _simulated_traffic(link_id: int) -> dict:
    seed = int(hashlib.md5(str(link_id).encode()).hexdigest()[:8], 16)
    base = 500_000 + (seed % 50) * 100_000
    return {
        "bps_in": base * 0.6,
        "bps_out": float(base),
        "util_pct": round((base / 1_000_000_000) * 100, 1),
        "source": "simulated",
    }


def get_link_traffic_map(session: Session, map_layer: str | None = None) -> dict[str, dict]:
    rows = session.execute(
        text(
            """
            SELECT nl.id, nl.map_layer, lower(nl.status::text) AS status,
                   lt.bps_in, lt.bps_out, lt.util_pct, lt.source
            FROM network_links nl
            LEFT JOIN link_traffic lt ON lt.link_id = nl.id
            WHERE lower(nl.protocol::text) = 'manual'
            """
        )
    ).all()
    result: dict[str, dict] = {}

    for link_id, link_layer, status, bps_in, bps_out, util_pct, source in rows:
        if map_layer and link_layer != map_layer:
            continue
        if bps_in is not None and bps_out is not None:
            result[str(link_id)] = {
                "bps_in": bps_in,
                "bps_out": bps_out,
                "util_pct": util_pct,
                "source": source or "simulated",
            }
        elif status == "active":
            result[str(link_id)] = _simulated_traffic(link_id)

    # Tráfego das conexões entre departamentos (mesmo padrão visual dos devices)
    device_dept_rows = session.execute(
        text(
            """
            SELECT device_id, parent_group_id
            FROM topology_layouts
            WHERE parent_group_id IS NOT NULL
              AND (:layer IS NULL OR map_layer = :layer)
            """
        ),
        {"layer": map_layer},
    ).all()
    device_to_dept: dict[int, int] = {
        device_id: parent_group_id for device_id, parent_group_id in device_dept_rows
    }

    cross_link_rows = session.execute(
        text(
            """
            SELECT id, source_device_id, target_device_id
            FROM network_links
            WHERE lower(protocol::text) = 'manual'
              AND (:layer IS NULL OR map_layer = :layer)
            """
        ),
        {"layer": map_layer},
    ).all()

    group_rows = session.execute(
        text(
            """
            SELECT id, source_group_id, target_group_id, lower(status::text) AS status, map_layer
            FROM topology_group_links
            WHERE (:layer IS NULL OR map_layer = :layer)
            """
        ),
        {"layer": map_layer},
    ).all()

    for gl_id, src_group_id, tgt_group_id, gl_status, gl_layer in group_rows:
        if map_layer and gl_layer != map_layer:
            continue
        key = f"glink-{gl_id}"
        agg_in = 0.0
        agg_out = 0.0
        for link_id, src_device_id, tgt_device_id in cross_link_rows:
            if not tgt_device_id:
                continue
            src_dept = device_to_dept.get(src_device_id)
            tgt_dept = device_to_dept.get(tgt_device_id)
            crosses = (src_dept == src_group_id and tgt_dept == tgt_group_id) or (
                src_dept == tgt_group_id and tgt_dept == src_group_id
            )
            if not crosses:
                continue
            device_traffic = result.get(str(link_id))
            if device_traffic:
                agg_in += float(device_traffic.get("bps_in") or 0)
                agg_out += float(device_traffic.get("bps_out") or 0)

        if agg_in > 0 or agg_out > 0:
            max_bps = max(agg_in, agg_out)
            result[key] = {
                "bps_in": agg_in,
                "bps_out": agg_out,
