def send_push_alert(subject: str, body: str) -> bool:
    from app.db_sync import SyncSession
    from app.models import PushToken

    with SyncSession() as session:
        tokens = session.execute(select(PushToken.token)).scalars().all()
        if not tokens:
            logger.info("Nenhum push token registrado. Alerta: %s", subject)
            return False

        messages = [
            {"to": token, "title": subject[:100], "body": body[:240], "sound": "default"}
            for token in tokens
        ]
        headers = {"Content-Type": "application/json"}
        if settings.expo_push_access_token:
