        try:
            with httpx.Client(timeout=15) as client:
                response = client.post("https://exp.host/--/api/v2/push/send", json=messages, headers=headers)
                if response.status_code == 200:
                    return True
                logger.error("Expo push failed (%s): %s", response.status_code, response.text[:300])
                return False
        except Exception as exc:
            logger.error("Expo push error: %s", exc)
            return False

from sqlalchemy import select
