from app.config import settings
from app.models import Alert, AlertRule, AlertStatus, Event, EventSeverity

_SEVERITY_RANK = {
    EventSeverity.INFO: 0,
    EventSeverity.WARNING: 1,
    EventSeverity.CRITICAL: 2,
    "info": 0,
    "warning": 1,
    "critical": 2,
}


def _severity_value(severity: EventSeverity | str) -> int:
    if isinstance(severity, EventSeverity):
        return _SEVERITY_RANK.get(severity, 0)
    return _SEVERITY_RANK.get(str(severity).lower(), 0)


def matching_rules(session: Session, event: Event) -> list[AlertRule]:
    rules = session.execute(
        select(AlertRule).where(AlertRule.is_enabled.is_(True)).order_by(AlertRule.id)
    ).scalars().all()
    matched: list[AlertRule] = []
    event_sev = _severity_value(event.severity)
    for rule in rules:
        if rule.event_type and rule.event_type != event.event_type:
            continue
        if event_sev < _severity_value(rule.min_severity):
            continue
        matched.append(rule)
    return matched


def channels_for_event(session: Session, event: Event) -> list[str]:
    """Resolve alert channels: matching rules override global defaults when any rule matches."""
    rules = matching_rules(session, event)
    if rules:
        channels: list[str] = []
        for rule in rules:
            for ch in rule.channels or []:
                ch_norm = str(ch).strip().lower()
                if ch_norm and ch_norm not in channels:
                    channels.append(ch_norm)
        if channels:
            return channels
    return settings.enabled_alert_channels


def queue_alerts_for_event_with_rules(session: Session, event: Event) -> list[Alert]:
    from app.services.alert_service import is_in_maintenance

    if is_in_maintenance(session):
        return []

    channels = channels_for_event(session, event)
    alerts: list[Alert] = []
    for channel in channels:
        existing = session.execute(
            select(Alert).where(Alert.event_id == event.id, Alert.channel == channel)
        ).scalar_one_or_none()
        if existing:
            continue
        alert = Alert(event_id=event.id, channel=channel, status=AlertStatus.PENDING)
        session.add(alert)
        alerts.append(alert)
    session.flush()
    return alerts

