    critical_events = session.execute(
        select(Event)
        .where(Event.created_at >= since, Event.severity == EventSeverity.CRITICAL)
        .order_by(Event.created_at.desc())
        .limit(5)
    ).scalars().all()
    pending_alerts = session.execute(
        select(func.count(Alert.id)).where(Alert.status == AlertStatus.PENDING)
    ).scalar() or 0
    anomalies = session.execute(
        select(func.count(AnomalyRecord.id)).where(AnomalyRecord.is_resolved.is_(False))
    ).scalar() or 0
    return {
        "devices_total": total,
        "devices_offline": offline,
        "pending_alerts": pending_alerts,
        "active_anomalies": anomalies,
        "recent_critical": [
            {"type": e.event_type, "message": e.message[:120], "at": e.created_at.isoformat()}
            for e in critical_events
        ],
    }


def _rules_reply(ctx: dict, user_message: str) -> tuple[str, list[str]]:
    msg = user_message.lower().strip()
    if any(w in msg for w in ("como usar", "o que é", "módulo", "zion", "mapa", "deepseek", "chatbot")):
        return (
            "Para perguntas sobre o produto SentinelAI (menus, módulos, configuração DeepSeek), "
            "use o **Chatbot** no menu ou o widget flutuante. Eu (NOC Copilot) foco em status operacional: "
            f"agora há {ctx['devices_offline']} offline, {ctx['pending_alerts']} alertas e "
            f"{ctx['active_anomalies']} anomalias.",
            ["Abrir Chatbot", "Resumo NOC", "Devices offline"],
        )
    if any(w in msg for w in ("offline", "down", "fora", "indispon")):
        return (
            f"Há {ctx['devices_offline']} dispositivo(s) offline de {ctx['devices_total']} monitorados. "
            "Recomendo verificar conectividade ICMP e revisar eventos `device_down` nas últimas 24h.",
            ["Ver dashboard", "Executar discovery", "Abrir mapa de rede"],
        )
    if any(w in msg for w in ("alerta", "alert", "crítico", "critical")):
        recent = ctx["recent_critical"]
        summary = "; ".join(r["message"][:60] for r in recent[:3]) if recent else "nenhum evento crítico recente"
        return (
            f"{ctx['pending_alerts']} alerta(s) pendente(s). Eventos críticos recentes: {summary}.",
            ["Abrir alertas", "Simular regra de alerta", "Ver relatório IA"],
        )
    if any(w in msg for w in ("anomalia", "anomaly", "latência", "latency")):
        return (
            f"{ctx['active_anomalies']} anomalia(s) de latência ativa(s). "
            "O detector roda a cada 15 min — revise métricas históricas dos devices afetados.",
            ["Relatórios & IA", "Ver métricas do device"],
        )
    if any(w in msg for w in ("resumo", "summary", "status", "situação")):
        uptime = ((ctx["devices_total"] - ctx["devices_offline"]) / ctx["devices_total"] * 100) if ctx["devices_total"] else 0
        return (
            f"Status NOC: {ctx['devices_total']} devices, {uptime:.0f}% online estimado, "
            f"{ctx['pending_alerts']} alertas pendentes, {ctx['active_anomalies']} anomalias.",
            ["Gerar relatório executivo", "Export PDF", "Relatório SOC2"],
        )
    return (
        "Sou o copilot NOC do SentinelAI. Posso ajudar com: dispositivos offline, alertas críticos, "
        "anomalias de latência e resumo operacional.",
        ["Resumo NOC", "Devices offline", "Alertas pendentes"],
    )


def noc_copilot_reply(session: Session, user_message: str) -> dict:
    ctx = build_noc_context(session)
    source = "rules-engine"
    llm_answer = None

    if llm_available():
        llm_answer = chat_completion(build_system_prompt(ctx), user_message)
        if llm_answer:
            source = settings.copilot_llm_provider

    if llm_answer:
        answer, actions = llm_answer, ["Ver dashboard", "Abrir alertas", "Relatório SOC2"]
    else:
        answer, actions = _rules_reply(ctx, user_message)

    return {
        "answer": answer,
        "suggested_actions": actions,
        "context_snapshot": ctx,
        "source": source,
    }

"""Cliente LLM OpenAI-compatible — OpenAI, DeepSeek API ou Ollama local.

DeepSeek (open-source / API): https://github.com/deepseek-ai
API cloud: https://api.deepseek.com (compatible com /v1/chat/completions)
Local: Ollama com modelo deepseek-r1 / deepseek-v3 em COPILOT_LLM_BASE_URL.
"""

from __future__ import annotations

import logging
from typing import Any

import httpx

from app.config import settings

logger = logging.getLogger(__name__)

PROVIDER_PRESETS: dict[str, dict[str, str]] = {
    "deepseek": {
        "base_url": "https://api.deepseek.com",
        "model": "deepseek-chat",
    },
    "openai": {
        "base_url": "https://api.openai.com/v1",
        "model": "gpt-4o-mini",
    },
    "ollama": {
        "base_url": "http://host.docker.internal:11434/v1",
        "model": "deepseek-r1:latest",
    },
}


def resolve_llm_config() -> dict[str, Any]:
    provider = (settings.copilot_llm_provider or "openai").lower().strip()
    preset = PROVIDER_PRESETS.get(provider, {})
    base_url = settings.copilot_llm_base_url.strip() or preset.get("base_url", "https://api.openai.com/v1")
    model = settings.copilot_llm_model.strip() or preset.get("model", "gpt-4o-mini")
    # DeepSeek API usa /chat/completions na raiz; aceitamos com ou sem /v1
    if provider == "deepseek" and base_url.rstrip("/").endswith("api.deepseek.com"):
        if not base_url.rstrip("/").endswith("/v1"):
            base_url = base_url.rstrip("/") + "/v1"
    return {
        "provider": provider,
        "base_url": base_url.rstrip("/"),
        "model": model,
        "api_key": settings.copilot_llm_api_key or ("ollama" if provider == "ollama" else ""),
        "max_tokens": settings.copilot_llm_max_tokens,
    }


def llm_available() -> bool:
    if not settings.copilot_llm_enabled:
        return False
    cfg = resolve_llm_config()
    if cfg["provider"] == "ollama":
        return True
    return bool(cfg["api_key"])


def chat_completion(system_prompt: str, user_message: str) -> str | None:
    return chat_completion_messages(
        [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": user_message},
        ]
    )


def chat_completion_messages(messages: list[dict[str, str]], *, temperature: float = 0.3) -> str | None:
    if not llm_available():
        return None

    cfg = resolve_llm_config()
    url = f"{cfg['base_url']}/chat/completions"
    headers = {"Content-Type": "application/json"}
    if cfg["api_key"]:
        headers["Authorization"] = f"Bearer {cfg['api_key']}"

    payload = {
        "model": cfg["model"],
        "messages": messages,
        "max_tokens": cfg["max_tokens"],
        "temperature": temperature,
    }
    try:
        with httpx.Client(timeout=60) as client:
            resp = client.post(url, headers=headers, json=payload)
        if resp.status_code != 200:
            logger.warning("LLM API error %s: %s", resp.status_code, resp.text[:300])
            return None
        data = resp.json()
        content = data["choices"][0]["message"]["content"]
        return (content or "").strip() or None
    except Exception as exc:
        logger.warning("LLM request failed: %s", exc)
        return None


def build_system_prompt(context: dict) -> str:
    critical = context.get("recent_critical") or []
    critical_text = "\n".join(f"- [{c['type']}] {c['message']}" for c in critical[:5]) or "Nenhum"
    provider = resolve_llm_config()["provider"]
    return f"""Você é o NOC Copilot do SentinelAI — assistente de operações de rede (NMS).
Motor LLM: {provider} (DeepSeek / OpenAI-compatible — ver https://github.com/deepseek-ai).
Responda em português, de forma concisa e acionável (máx. 3 parágrafos curtos).

Contexto operacional atual:
- Devices totais: {context.get('devices_total', 0)}
- Devices offline: {context.get('devices_offline', 0)}
- Alertas pendentes: {context.get('pending_alerts', 0)}
- Anomalias ativas: {context.get('active_anomalies', 0)}
- Eventos críticos recentes:
{critical_text}

Regras:
- Sugira ações práticas no SentinelAI (Dashboard, Alertas, Mapa, Scanner, Zion, Discovery).
- Não invente devices, IPs ou métricas que não estejam no contexto.
- Se a pergunta for sobre o produto (como usar um módulo), explique o caminho no menu."""

