        "como configurar DeepSeek/Ollama e caminhos no menu. Pergunte, por exemplo: "
        "\"como faço discovery SNMP?\" ou \"o que o Zion faz?\".",
        ["O que é Zion?", "Como configurar DeepSeek?", "Mapa de Rede"],
    )


def build_chatbot_system_prompt(noc_ctx: dict | None, snippets: list[str]) -> str:
    cfg = resolve_llm_config()
    knowledge = build_knowledge_corpus()
    # Limita tamanho do prompt; snippets priorizam a pergunta
    if len(knowledge) > 12000:
        knowledge = knowledge[:12000] + "\n…(truncado)"
    snippet_block = "\n".join(f"- {s}" for s in snippets) or "- (nenhum trecho específico)"
    live = ""
    if noc_ctx:
        live = (
            f"\nEstado live (opcional):\n"
            f"- devices={noc_ctx.get('devices_total')} offline={noc_ctx.get('devices_offline')} "
            f"alertas={noc_ctx.get('pending_alerts')} anomalias={noc_ctx.get('active_anomalies')}\n"
        )
    return f"""Você é o Chatbot oficial do SentinelAI — especialista no produto (NMS + Map Editor).
Motor: {cfg['provider']} / modelo {cfg['model']} (ecossistema DeepSeek open-source: https://github.com/deepseek-ai).
Responda em português, claro e objetivo. Cite o caminho do menu quando ensinar a usar algo.
Não invente features que não estejam na base de conhecimento abaixo.
Se a pergunta for operacional (quantos offline?), use o estado live se existir; senão oriente a usar o NOC Copilot.

Trechos relevantes à pergunta:
{snippet_block}
{live}
--- BASE DE CONHECIMENTO ---
{knowledge}
"""


def chatbot_reply(
    session: Session,
    user_message: str,
    *,
    history: list[dict[str, str]] | None = None,
    include_live: bool = True,
) -> dict:
    snippets = search_knowledge(user_message)
    noc_ctx = build_noc_context(session) if include_live else None
    source = "rules-engine"
    answer = None

    if llm_available():
        messages: list[dict[str, str]] = [
            {"role": "system", "content": build_chatbot_system_prompt(noc_ctx, snippets)},
        ]
        for turn in (history or [])[-8:]:
            role = turn.get("role")
            content = (turn.get("content") or "").strip()
            if role in ("user", "assistant") and content:
                messages.append({"role": role, "content": content[:2000]})
        messages.append({"role": "user", "content": user_message})
        answer = chat_completion_messages(messages, temperature=0.4)
        if answer:
            source = settings.copilot_llm_provider

    if not answer:
        answer, actions = _rules_product_reply(user_message, snippets)
    else:
        actions = ["Abrir Dashboard", "NOC Copilot", "Zion", "Mapa de Rede"]

    return {
        "answer": answer,
        "suggested_actions": actions,
        "source": source,
        "provider": resolve_llm_config()["provider"] if llm_available() else "rules-engine",
        "model": resolve_llm_config()["model"] if llm_available() else None,
        "llm_enabled": llm_available(),
        "knowledge_hits": snippets[:8],
        "context_snapshot": noc_ctx or {},
    }


def chatbot_status() -> dict:
    cfg = resolve_llm_config()
    return {
        "llm_enabled": llm_available(),
        "provider": cfg["provider"],
        "model": cfg["model"],
        "base_url": cfg["base_url"],
        "deepseek_docs": "https://github.com/deepseek-ai",
        "modes": {
            "chatbot": "Ajuda sobre o produto SentinelAI (features, menus, configuração)",
            "noc_copilot": "Assistente operacional (devices, alertas, anomalias)",
        },
    }

"""Network map vision analysis (GPT-4o vision or rules fallback)."""

import base64
import logging

import httpx

from app.config import settings

logger = logging.getLogger(__name__)


def vision_available() -> bool:
    return settings.map_vision_enabled and bool(settings.copilot_llm_api_key)


def analyze_map_image(image_base64: str, context: dict) -> str | None:
    if not vision_available():
        return None

    url = f"{settings.copilot_llm_base_url.rstrip('/')}/chat/completions"
    headers = {
        "Authorization": f"Bearer {settings.copilot_llm_api_key}",
        "Content-Type": "application/json",
    }
    b64 = image_base64.split(",")[-1] if "," in image_base64 else image_base64
    prompt = (
        "Analise este mapa de rede do SentinelAI. Identifique: pontos únicos de falha, "
        "links críticos, devices isolados e recomendações NOC. Responda em português, "
        f"máx. 4 parágrafos. Contexto: {context.get('nodes', 0)} nodes, "
        f"{context.get('edges', 0)} links, {context.get('offline', 0)} offline."
    )
    payload = {
        "model": settings.map_vision_model,
        "messages": [
            {
                "role": "user",
                "content": [
                    {"type": "text", "text": prompt},
                    {"type": "image_url", "image_url": {"url": f"data:image/png;base64,{b64}"}},
                ],
            }
        ],
        "max_tokens": 600,
        "temperature": 0.2,
    }
    try:
        with httpx.Client(timeout=45) as client:
            resp = client.post(url, headers=headers, json=payload)
        if resp.status_code != 200:
            logger.warning("Vision API error %s", resp.status_code)
            return None
        return resp.json()["choices"][0]["message"]["content"].strip()
    except Exception as exc:
        logger.warning("Vision request failed: %s", exc)
        return None


def rules_map_analysis(context: dict) -> tuple[str, list[str]]:
    nodes = context.get("nodes", 0)
    edges = context.get("edges", 0)
    offline = context.get("offline", 0)
    groups = context.get("groups", 0)
    findings: list[str] = []
    if offline > 0:
        findings.append(f"{offline} device(s) offline — verificar conectividade e redundância")
    if nodes > 0 and edges < nodes - 1:
        findings.append("Topologia possivelmente fragmentada — poucos links para a quantidade de nodes")
    if groups == 0 and nodes > 5:
        findings.append("Considere agrupar devices por site/rack no mapa para melhor visibilidade")
    if not findings:
        findings.append("Topologia estável — nenhum risco imediato detectado")
    analysis = (
        f"Análise estrutural do mapa ({nodes} nodes, {edges} links, {groups} grupos): "
        + " ".join(findings)
    )
    return analysis, findings

