from datetime import UTC, datetime

from app.db_sync import SyncSession
from app.engines.reporting.exporters import export_devices_excel, export_events_excel, export_summary_pdf
from app.models import DiscoveryJobStatus, ReportJob
from app.workers.celery_app import celery_app


@celery_app.task(name="app.workers.report_tasks.generate_report")
def generate_report_task(job_id: int, days: int = 7) -> dict:
    with SyncSession() as session:
        job = session.get(ReportJob, job_id)
        if not job:
            return {"error": "job not found"}

        job.status = DiscoveryJobStatus.RUNNING
        session.commit()

        try:
            if job.report_type == "devices" and job.format == "xlsx":
                path = export_devices_excel(session)
                job.summary = None
            elif job.report_type == "events" and job.format == "xlsx":
                path = export_events_excel(session)
                job.summary = None
            elif job.report_type == "summary" and job.format == "pdf":
                path, summary = export_summary_pdf(session, days=days)
                job.summary = summary
            else:
                raise ValueError(f"Combinação inválida: {job.report_type}/{job.format}")

            job.file_path = path
            job.status = DiscoveryJobStatus.COMPLETED
            job.completed_at = datetime.now(UTC)
        except Exception as exc:
            job.status = DiscoveryJobStatus.FAILED
            job.error_message = str(exc)
            job.completed_at = datetime.now(UTC)

        session.commit()
        return {"job_id": job_id, "status": job.status.value}


@celery_app.task(name="app.workers.report_tasks.generate_weekly_report")
def generate_weekly_report() -> dict:
    with SyncSession() as session:
        job = ReportJob(report_type="summary", format="pdf")
        session.add(job)
        session.commit()
        job_id = job.id
    generate_report_task.delay(job_id, 7)
    return {"job_id": job_id}

import asyncio
import logging

from app.db_sync import SyncSession
from app.engines.config.ssh_backup import backup_device_config
from app.engines.netflow.collector import drain_flow_records
from app.models import Device
from app.services.enterprise_service import save_config_backup, store_flow_records
from app.workers.celery_app import celery_app

logger = logging.getLogger(__name__)


@celery_app.task(name="app.workers.enterprise_tasks.persist_flow_records")
def persist_flow_records() -> dict:
    async def _run() -> list[dict]:
        return await drain_flow_records()

    try:
        records = asyncio.run(_run())
    except RuntimeError:
        records = []

    if not records:
        return {"stored": 0}

    with SyncSession() as session:
        count = store_flow_records(session, records)
        session.commit()
    return {"stored": count}


@celery_app.task(name="app.workers.enterprise_tasks.run_config_backup")
def run_config_backup(device_id: int) -> dict:
    with SyncSession() as session:
        device = session.get(Device, device_id)
        if not device:
            return {"error": "device not found"}
        try:
            extra = device.extra_data or {}
            ssh = extra.get("ssh") or {}
            content, content_hash = backup_device_config(
                device.ip_address,
                username=ssh.get("username"),
                password=ssh.get("password"),
            )
            backup = save_config_backup(session, device_id, content, content_hash)
