from app.db_sync import SyncSession
from app.engines.discovery.snmp_collector import _snmp_get
from app.engines.snmp.trap_collector import drain_traps
from app.models import CustomOidPoll
from app.services.phase10_service import store_traps
from app.workers.celery_app import celery_app


@celery_app.task(name="app.workers.phase10_tasks.persist_snmp_traps")
def persist_snmp_traps() -> dict:
    async def _run() -> list[dict]:
        return await drain_traps()

    try:
        traps = asyncio.run(_run())
    except RuntimeError:
        traps = []

    if not traps:
        return {"stored": 0}

    with SyncSession() as session:
        count = store_traps(session, traps)
        session.commit()
    return {"stored": count}


@celery_app.task(name="app.workers.phase10_tasks.poll_custom_oids")
def poll_custom_oids() -> dict:
    from datetime import UTC, datetime

    polled = 0
    with SyncSession() as session:
        rows = session.execute(select(CustomOidPoll).where(CustomOidPoll.is_enabled.is_(True))).scalars().all()
        for row in rows:
            from app.models import Device

            dev = session.get(Device, row.device_id)
            if not dev:
                continue
            raw = _snmp_get(dev.ip_address, row.oid)
            if raw is None:
                continue
            try:
                row.last_value = float(raw)
            except ValueError:
                continue
            row.last_polled_at = datetime.now(UTC)
            session.add(row)
            polled += 1
        session.commit()
    return {"polled": polled}


