class MikrotikPlugin(BasePlugin):
    key = "mikrotik"
    name = "Mikrotik API"
    description = "Coleta recursos via RouterOS REST API"

    def run(self, config: dict) -> PluginResult:
        host = config.get("host")
        username = config.get("username", "admin")
        password = config.get("password", "")
        if not host:
            return PluginResult(False, "host obrigatório")
        try:
            url = f"http://{host}/rest/system/resource"
            with httpx.Client(timeout=10, verify=False) as client:
                resp = client.get(url, auth=(username, password))
            if resp.status_code != 200:
                return PluginResult(False, f"HTTP {resp.status_code}")
            data = resp.json()
            return PluginResult(True, "OK", {"resource": data})
        except Exception as exc:
            logger.debug("Mikrotik plugin error: %s", exc)
            return PluginResult(False, str(exc))


class VmwarePlugin(BasePlugin):
    key = "vmware"
    name = "VMware vSphere"
    description = "Inventário VMs via vCenter REST (pyvmomi opcional)"

    def run(self, config: dict) -> PluginResult:
        host = config.get("host")
        username = config.get("username")
        password = config.get("password")
        if not host:
            return PluginResult(False, "host vCenter obrigatório")
        vms: list[dict] = []
        try:
            from pyVim.connect import SmartConnect, Disconnect
            from pyVmomi import vim
            import ssl

            ctx = ssl.create_default_context()
            ctx.check_hostname = False
            ctx.verify_mode = ssl.CERT_NONE
            si = SmartConnect(host=host, user=username, pwd=password, sslContext=ctx)
            content = si.RetrieveContent()
            container = content.viewManager.CreateContainerView(content.rootFolder, [vim.VirtualMachine], True)
            for vm in container.view:
                summary = vm.summary
                vms.append(
                    {
                        "name": summary.config.name,
                        "vmid": summary.config.uuid,
                        "status": str(summary.runtime.powerState),
                        "host": summary.runtime.host.name if summary.runtime.host else None,
                    }
                )
            Disconnect(si)
            return PluginResult(True, f"{len(vms)} VMs", {"vms": vms, "vm_count": len(vms)})
        except ImportError:
            return PluginResult(True, f"vCenter {host} (instale pyvmomi para inventário real)", {"vms": [], "vm_count": 0})
        except Exception as exc:
            return PluginResult(False, str(exc))


