class AwsEc2Plugin(BasePlugin):
    key = "aws_ec2"
    name = "AWS EC2 Inventory"
    description = "Lista instâncias EC2 via boto3"

    def run(self, config: dict) -> PluginResult:
        region = config.get("region")
        if not region:
            return PluginResult(False, "region obrigatória")
        try:
            import boto3

            session = boto3.Session(
                aws_access_key_id=config.get("access_key_id"),
                aws_secret_access_key=config.get("secret_access_key"),
                region_name=region,
            )
            ec2 = session.client("ec2")
            paginator = ec2.get_paginator("describe_instances")
            vms: list[dict] = []
            for page in paginator.paginate():
                for reservation in page.get("Reservations", []):
                    for inst in reservation.get("Instances", []):
                        name = next(
                            (t["Value"] for t in inst.get("Tags", []) if t.get("Key") == "Name"),
                            inst.get("InstanceId"),
                        )
                        vms.append(
                            {
                                "name": name,
                                "vmid": inst.get("InstanceId"),
                                "status": inst.get("State", {}).get("Name"),
                                "type": inst.get("InstanceType"),
                            }
                        )
            return PluginResult(True, f"{len(vms)} instâncias", {"instances": vms, "vm_count": len(vms)})
        except ImportError:
            return PluginResult(True, f"AWS {region} (instale boto3)", {"instances": [], "vm_count": 0})
        except Exception as exc:
            return PluginResult(False, str(exc))


