"""HashiCorp Vault integration (KV v2 secrets)."""

import logging

import httpx

from app.config import settings

logger = logging.getLogger(__name__)


def get_vault_status() -> dict:
    if not settings.vault_enabled:
        return {"enabled": False, "status": "disabled"}
    try:
        with httpx.Client(timeout=5) as client:
            resp = client.get(
                f"{settings.vault_addr.rstrip('/')}/v1/sys/health",
                headers=_headers(),
            )
        data = resp.json() if resp.content else {}
        return {
            "enabled": True,
            "status": "ok" if resp.status_code in (200, 429, 472, 473) else "error",
            "initialized": data.get("initialized"),
            "sealed": data.get("sealed"),
            "version": data.get("version"),
        }
    except Exception as exc:
        return {"enabled": True, "status": "error", "message": str(exc)}


def read_secret(path: str) -> dict | None:
    if not settings.vault_enabled:
        return None
    try:
        mount = settings.vault_mount.strip("/")
        url = f"{settings.vault_addr.rstrip('/')}/v1/{mount}/data/{path.lstrip('/')}"
        with httpx.Client(timeout=5) as client:
            resp = client.get(url, headers=_headers())
        if resp.status_code != 200:
            return None
        return resp.json().get("data", {}).get("data", {})
    except Exception as exc:
        logger.debug("Vault read failed: %s", exc)
        return None


def resolve_secret(key: str, fallback: str = "") -> str:
    """Read secret from Vault or fall back to settings/env."""
    if settings.vault_enabled:
        data = read_secret(settings.vault_secret_path)
        if data and key in data:
            return str(data[key])
    return fallback


def _headers() -> dict:
    headers = {}
    if settings.vault_token:
        headers["X-Vault-Token"] = settings.vault_token
    return headers

