    }


def list_playbook_marketplace_with_ratings(session: Session) -> list[dict]:
    base = list_playbook_marketplace(session)
    for item in base:
        stats = session.execute(
            select(func.avg(PlaybookMarketplaceReview.rating), func.count(PlaybookMarketplaceReview.id)).where(
                PlaybookMarketplaceReview.playbook_slug == item["slug"]
            )
        ).one()
        avg, count = stats
        item["avg_rating"] = round(float(avg), 1) if avg is not None else 0.0
        item["review_count"] = int(count or 0)
    return base


def list_playbook_reviews(session: Session, playbook_slug: str, limit: int = 20) -> list[PlaybookMarketplaceReview]:
    return list(
        session.execute(
            select(PlaybookMarketplaceReview)
            .where(PlaybookMarketplaceReview.playbook_slug == playbook_slug)
            .order_by(PlaybookMarketplaceReview.created_at.desc())
            .limit(limit)
        ).scalars().all()
    )


def submit_playbook_review(session: Session, playbook_slug: str, username: str, rating: int, comment: str) -> PlaybookMarketplaceReview:
    catalog_slugs = {p["slug"] for p in PLAYBOOK_MARKETPLACE_CATALOG}
    if playbook_slug not in catalog_slugs:
        raise ValueError("Playbook não existe no marketplace")
    row = PlaybookMarketplaceReview(
        playbook_slug=playbook_slug,
        username=username,
        rating=rating,
        comment=comment or None,
    )
    session.add(row)
    session.flush()
    return row


