def run_cdn_intelligent_auto_purge() -> dict:
    from app.services.phase20_service import get_cdn_cost_optimization

    if not settings.cdn_auto_purge_enabled:
        return {
            "enabled": False,
            "purge_id": "",
            "paths": [],
            "reason": "CDN auto-purge desabilitado",
            "estimated_savings_usd": 0.0,
            "provider": settings.cdn_provider,
        }

    opt = get_cdn_cost_optimization(24)
    recs = [r for r in opt.get("recommendations", []) if r.get("priority") in ("high", "medium")]
    paths = ["/*"]
    if any(r.get("id") == "rec-regional-origin" for r in recs):
        regions = [r.strip() for r in settings.agent_cdn_regions.split(",") if r.strip()]
        paths = [f"/{reg}/*" for reg in regions[:3]] or ["/*"]

    purge_id = f"auto_{secrets.token_hex(6)}"
    savings = float(opt.get("projected_savings_usd", 0))
    reason = recs[0]["title"] if recs else "Manutenção preventiva de cache"
    return {
        "enabled": True,
        "purge_id": purge_id,
        "paths": paths,
        "reason": reason,
        "estimated_savings_usd": savings,
        "provider": settings.cdn_provider,
    }


def seed_auditor_tenant_billing(session: Session) -> int:
    portals = session.execute(select(AuditorTenantPortal)).scalars().all()
    updated = 0
    for portal in portals:
        if portal.monthly_fee_cents <= 0:
            portal.monthly_fee_cents = DEFAULT_AUDITOR_TENANT_FEE_CENTS
            portal.billing_status = "active"
            updated += 1
    return updated


def get_auditor_tenant_billing(session: Session) -> dict:
    rows = session.execute(
        select(AuditorTenantPortal, Organization)
        .join(Organization, Organization.id == AuditorTenantPortal.org_id)
        .where(AuditorTenantPortal.is_active.is_(True))
    ).all()
    currency = settings.billing_default_currency
    symbol = SUPPORTED_CURRENCIES.get(currency, {}).get("symbol", "R$")
    tenants = []
    total = 0
    for portal, org in rows:
        fee = portal.monthly_fee_cents or DEFAULT_AUDITOR_TENANT_FEE_CENTS
        total += fee
        tenants.append({
            "tenant_slug": portal.slug,
            "org_name": org.name,
            "brand_name": portal.brand_name,
            "monthly_fee_cents": fee,
            "currency": currency,
            "formatted_fee": f"{symbol} {fee / 100:.2f}",
            "status": portal.billing_status,
        })
    return {
        "enabled": settings.auditor_tenant_billing_enabled,
        "currency": currency,
        "total_mrr_cents": total,
        "tenants": tenants,
    }


def seed_default_playbook_reviews(session: Session) -> int:
    existing = session.execute(select(func.count(PlaybookMarketplaceReview.id))).scalar() or 0
    if existing > 0:
        return 0
    seeds = [
        ("mp-dns-flush", "admin", 5, "Resolveu queda de DNS rapidamente"),
        ("mp-cert-expiry-check", "operator", 4, "Bom para compliance TLS"),
        ("mp-backup-verify", "admin", 5, "Essencial para auditoria"),
    ]
    for slug, user, rating, comment in seeds:
        session.add(PlaybookMarketplaceReview(playbook_slug=slug, username=user, rating=rating, comment=comment))
    return len(seeds)

