export default function App() {
  const [page, setPage] = useState<AppPage>("dashboard");
  const [authenticated, setAuthenticated] = useState(Boolean(getToken()));
  const [booting, setBooting] = useState(Boolean(getToken()));

  useEffect(() => {
    if (!getToken()) {
      setBooting(false);
      return;
    }
    fetchMe()
      .then(() => setAuthenticated(true))
      .catch(() => {
        clearToken();
        setAuthenticated(false);
      })
      .finally(() => setBooting(false));
  }, []);

  if (booting) {
    return (
      <ThemeProvider>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: "0.75rem", padding: "3rem" }}>
          <span className="sa-spinner" />
          <span style={{ color: "var(--sa-text-muted)" }}>A verificar sessão...</span>
        </div>
      </ThemeProvider>
    );
  }

  if (!authenticated) {
    return (
      <ThemeProvider>
        <ErrorBoundary>
          <LoginPage onLogin={() => setAuthenticated(true)} />
        </ErrorBoundary>
      </ThemeProvider>
    );
  }

  return (
    <ThemeProvider>
      <AuthProvider>
        <ErrorBoundary>
        <AppShell
          page={page}
          onNavigate={setPage}
          onLogout={() => {
            clearToken();
            setAuthenticated(false);
          }}
        >
          <ErrorBoundary key={page}>
            {page === "dashboard" && <Dashboard />}
            {page === "topology" && <TopologyMap />}
            {page === "scanner" && <ScannerPage />}
            {page === "reports" && <ReportsPage />}
            {page === "copilot" && <NocCopilotPage />}
            {page === "chatbot" && <ChatbotPage />}
            {page === "alerts" && <AlertsPage />}
            {page === "infra" && <InfrastructurePage />}
            {page === "platform" && <PlatformPage />}
            {page === "users" && <UsersPage />}
            {page === "zion" && <ZionPage />}
          </ErrorBoundary>
        </AppShell>
        </ErrorBoundary>
      </AuthProvider>
    </ThemeProvider>
  );
}

