export { getToken };

export function formatApiError(err: unknown): string {
  if (err instanceof DOMException && (err.name === "TimeoutError" || err.name === "AbortError")) {
    return "Tempo esgotado ao contactar a API. Verifique se o backend está ativo (porta 8000).";
  }
  if (err instanceof Error) {
    const msg = err.message;
    if (/signal timed out|TimeoutError|aborted due to timeout/i.test(msg)) {
      return "Tempo esgotado ao contactar a API. Verifique se o backend está ativo (porta 8000).";
    }
    if (msg === "Failed to fetch" || /NetworkError|network/i.test(msg)) {
      return "Não foi possível ligar à API. Confirme que o backend está a correr.";
    }
    return msg;
  }
  return String(err);
}

async function request<T>(path: string, options: RequestInit = {}): Promise<T> {
  const token = getToken();
  const headers: Record<string, string> = {
    ...(options.headers as Record<string, string> | undefined),
  };

  if (token) {
    headers.Authorization = `Bearer ${token}`;
  }

  if (!(options.body instanceof FormData)) {
    headers["Content-Type"] = headers["Content-Type"] ?? "application/json";
  }

  let response: Response;
  try {
    response = await fetch(`${API_BASE}${path}`, {
      ...options,
      headers,
      signal: options.signal ?? AbortSignal.timeout(12000),
    });
  } catch (err) {
    throw new Error(formatApiError(err));
  }

  if (!response.ok) {
    const text = await response.text();
    if (response.status === 422) {
      let message = "Parâmetros de scan inválidos. Verifique o perfil selecionado.";
      try {
        const detail = JSON.parse(text) as { detail?: Array<{ msg?: string }> };
        if (Array.isArray(detail.detail) && detail.detail[0]?.msg) {
          message = detail.detail[0].msg;
        }
      } catch {
        /* use default message */
      }
      throw new Error(message);
    }
    const err = new Error(text || `Erro ${response.status}`);
    (err as Error & { status?: number }).status = response.status;
    throw err;
  }

  if (response.status === 204) {
    return undefined as T;
  }

  return response.json() as Promise<T>;
}

export async function login(username: string, password: string): Promise<void> {
  const body = new URLSearchParams({ username, password });
  let response: Response;
  try {
    response = await fetch(`${API_BASE}/api/auth/login`, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body,
      signal: AbortSignal.timeout(15000),
    });
  } catch {
    throw new Error("Não foi possível conectar à API. Verifique se o serviço está online.");
  }

  if (response.status === 401) {
    throw new Error("Usuário ou senha inválidos");
  }
  if (!response.ok) {
    throw new Error(`Erro no login (${response.status}). Tente novamente.`);
  }

  const data = (await response.json()) as { access_token: string };
  setToken(data.access_token);
}

export function fetchDevices(options?: { onMap?: boolean; limit?: number }): Promise<Device[]> {
  const limit = Math.min(Math.max(options?.limit ?? 2500, 1), 2500);
  const params = new URLSearchParams();
  params.set("limit", String(limit));
  if (options?.onMap) params.set("on_map", "true");
  return request<Device[]>(`/api/devices?${params.toString()}`);
}

export function fetchDevice(deviceId: number): Promise<Device> {
  return request<Device>(`/api/devices/${deviceId}`);
}

export function enrichDevice(deviceId: number): Promise<Device> {
  return request<Device>(`/api/devices/${deviceId}/enrich`, { method: "POST" });
}

export function updateDevice(
  deviceId: number,
  data: Partial<Pick<Device, "hostname" | "vendor" | "model" | "mac_address">>,
): Promise<Device> {
  return request<Device>(`/api/devices/${deviceId}`, { method: "PATCH", body: JSON.stringify(data) });
}

export function fetchEvents(limit = 100): Promise<Event[]> {
  return request<Event[]>(`/api/events?limit=${Math.min(Math.max(limit, 1), 100)}`);
}

export function fetchDiscoveryJobs(): Promise<DiscoveryJob[]> {
  return request<DiscoveryJob[]>("/api/discovery?limit=10");
}

export function fetchScanDefaults(): Promise<ScanDefaultsResponse> {
  return request<ScanDefaultsResponse>("/api/discovery/scan-defaults");
}

export function startDiscovery(
  subnet: string,
  options: { useSnmp?: boolean; snmpCommunity?: string; scanOptions?: ScanOptionsPayload } = {},
): Promise<DiscoveryJob> {
  const { useSnmp = true, snmpCommunity, scanOptions } = options;
  const payload = scanOptions ?? { profile: "standard" as const, use_snmp: useSnmp };
  return request<DiscoveryJob>("/api/discovery", {
    method: "POST",
    body: JSON.stringify({
      subnet,
      use_snmp: payload.use_snmp ?? useSnmp,
      snmp_community: snmpCommunity ?? payload.snmp_community ?? null,
      scan_options: payload,
    }),
  });
}

export function stopDiscoveryJob(jobId: number): Promise<DiscoveryJob> {
  return request<DiscoveryJob>(`/api/discovery/${jobId}/stop`, { method: "POST" });
}

export function fetchDeviceHistory(deviceId: number): Promise<DeviceHistoryEntry[]> {
  return request<DeviceHistoryEntry[]>(`/api/devices/${deviceId}/history`);
}

export function fetchDeviceSoftware(deviceId: number): Promise<DeviceSoftware> {
  return request<DeviceSoftware>(`/api/devices/${deviceId}/software`);
}

export function refreshDeviceSoftware(deviceId: number): Promise<DeviceSoftware> {
  return request<DeviceSoftware>(`/api/devices/${deviceId}/software/refresh`, { method: "POST" });
}

export function fetchDeviceHardware(deviceId: number): Promise<DeviceHardware> {
  return request<DeviceHardware>(`/api/devices/${deviceId}/hardware`);
}

export function registerPushToken(token: string, platform = "expo"): Promise<{ id: number; platform: string; created_at: string }> {
  return request("/api/mobile/push-token", {
    method: "POST",
    body: JSON.stringify({ token, platform }),
  });
}

export function createDevice(ip_address: string, hostname?: string): Promise<Device> {
  return request<Device>("/api/devices", {
    method: "POST",
    body: JSON.stringify({ ip_address, hostname: hostname || null }),
  });
}

export function retireDevice(deviceId: number): Promise<void> {
  return request(`/api/devices/${deviceId}`, { method: "DELETE" });
}

export async function importCsv(file: File): Promise<{ imported: number; skipped: number; errors: string[] }> {
  const form = new FormData();
  form.append("file", file);
  return request("/api/devices/import/csv", { method: "POST", body: form });
}

