  const loadData = useCallback(async () => {
    const maxAttempts = 2;
    let lastError: unknown;
    for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
      try {
        const [deviceList, eventList, jobList] = await Promise.all([
          fetchDevices({ onMap: true, limit: 2500 }),
          fetchEvents(100),
          fetchDiscoveryJobs(),
        ]);
        setDevices(deviceList.slice(0, 2500));
        setEvents(eventList.slice(0, 100));
        setJobs(jobList);
        return;
      } catch (err) {
        lastError = err;
        const status = (err as Error & { status?: number }).status;
        const msg = err instanceof Error ? err.message : String(err);
        if (status === 401 || msg.includes("401") || msg.toLowerCase().includes("unauthorized")) {
          throw err;
        }
        if (attempt < maxAttempts) {
          await new Promise((resolve) => setTimeout(resolve, 1000));
        }
      }
    }
    throw lastError;
