export function DeviceDetailPanel({
  device,
  history,
  enriching = false,
  onClose,
  onDeviceUpdated,
}: {
  device: Device;
  history: DeviceHistoryEntry[];
  enriching?: boolean;
  onClose: () => void;
  onDeviceUpdated?: (device: Device) => void;
}) {
  const { canWrite } = useAuth();
  const [tab, setTab] = useState<"resumo" | "hardware" | "metricas" | "monitores" | "config" | "interfaces" | "software" | "historico">("resumo");
  const [editHostname, setEditHostname] = useState(device.hostname ?? "");
  const [editVendor, setEditVendor] = useState(device.vendor ?? "");
  const [editModel, setEditModel] = useState(device.model ?? "");
  const [editMac, setEditMac] = useState(device.mac_address ?? "");
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);
  const [software, setSoftware] = useState<DeviceSoftware | null>(null);
  const [softwareLoading, setSoftwareLoading] = useState(false);
  const [softwareError, setSoftwareError] = useState<string | null>(null);
  const [hardware, setHardware] = useState<DeviceHardware | null>(null);
  const [hardwareLoading, setHardwareLoading] = useState(false);
  const [hardwareError, setHardwareError] = useState<string | null>(null);

  useEffect(() => {
    setEditHostname(device.hostname ?? "");
    setEditVendor(device.vendor ?? "");
    setEditModel(device.model ?? "");
    setEditMac(device.mac_address ?? "");
    setSoftware(null);
    setHardware(null);
  }, [device]);

  useEffect(() => {
    if (tab !== "hardware") return;
    setHardwareLoading(true);
    setHardwareError(null);
    fetchDeviceHardware(device.id)
      .then(setHardware)
      .catch((err) => setHardwareError(String(err)))
      .finally(() => setHardwareLoading(false));
  }, [tab, device.id]);

  useEffect(() => {
    if (tab !== "software") return;
    setSoftwareLoading(true);
    setSoftwareError(null);
    fetchDeviceSoftware(device.id)
      .then(setSoftware)
      .catch((err) => setSoftwareError(String(err)))
      .finally(() => setSoftwareLoading(false));
  }, [tab, device.id]);

  const snmp = device.extra_data?.snmp as Record<string, unknown> | undefined;
  const wmi = device.extra_data?.wmi as Record<string, unknown> | undefined;
  const softwareCount = (device.extra_data?.software as { count?: number } | undefined)?.count ?? 0;
  const interfaces = (snmp?.interfaces as Array<{ name: string; status: string; index: number }>) ?? [];
  const enrichmentSources = (device.extra_data?.enrichment as { sources?: string[] } | undefined)?.sources ?? [];

  async function handleSaveIdentity() {
    setSaving(true);
    setSaveError(null);
    try {
      const updated = await updateDevice(device.id, {
        hostname: editHostname.trim() || null,
        vendor: editVendor.trim() || null,
        model: editModel.trim() || null,
        mac_address: editMac.trim() || null,
      });
      onDeviceUpdated?.(updated);
    } catch {
      setSaveError("Erro ao salvar dados do dispositivo.");
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="sa-detail-panel">
      <div className="sa-card-header">
        <div>
          <h3>{device.ip_address}</h3>
          <p>{device.hostname ?? "Sem hostname"} · {getDeviceTypeLabel(device.device_type)}</p>
        </div>
        <button type="button" className="sa-btn sa-btn-ghost sa-btn-sm" onClick={onClose}>
          Fechar
        </button>
      </div>

      <div className="sa-card-body">
        <div className="sa-tabs">
          {([
            ["resumo", "Resumo"],
            ["hardware", "Hardware"],
            ["metricas", "Métricas & SLA"],
            ["monitores", "Monitores"],
            ["config", "Config backup"],
            ["interfaces", `Interfaces (${interfaces.length})`],
            ["software", `Software (${softwareCount || software?.count || 0})`],
            ["historico", `Histórico (${history.length})`],
          ] as const).map(([t, label]) => (
            <button
              key={t}
              type="button"
              className={`sa-tab ${tab === t ? "sa-tab-active" : ""}`}
              onClick={() => setTab(t)}
            >
              {label}
            </button>
          ))}
        </div>

        {tab === "resumo" && (
          <div className="sa-detail-grid">
            {enriching && (
              <p className="sa-detail-enriching sa-detail-wide">
                <span className="sa-spinner" /> Coletando hostname, vendor, modelo e MAC...
              </p>
            )}
            {!enriching && enrichmentSources.length > 0 && (
              <p className="sa-detail-meta sa-detail-wide">
                Fontes: {enrichmentSources.join(", ")}
                {!device.mac_address && " · MAC requer SNMP na rede local ou preenchimento manual"}
              </p>
            )}
            <div className="sa-detail-item"><span>Status</span><strong><StatusBadge status={device.status} /></strong></div>
            <div className="sa-detail-item"><span>IP</span><strong>{device.ip_address}</strong></div>
            {canWrite ? (
              <>
                <div className="sa-detail-item">
                  <span>Hostname</span>
                  <input className="sa-input" value={editHostname} onChange={(e) => setEditHostname(e.target.value)} placeholder="hostname.exemplo.local" />
                </div>
                <div className="sa-detail-item">
                  <span>Vendor</span>
                  <input className="sa-input" value={editVendor} onChange={(e) => setEditVendor(e.target.value)} placeholder="Fabricante" />
                </div>
                <div className="sa-detail-item">
                  <span>Modelo</span>
                  <input className="sa-input" value={editModel} onChange={(e) => setEditModel(e.target.value)} placeholder="Modelo" />
                </div>
                <div className="sa-detail-item">
                  <span>MAC</span>
                  <input className="sa-input" value={editMac} onChange={(e) => setEditMac(e.target.value)} placeholder="AA:BB:CC:DD:EE:FF" />
                </div>
                <div className="sa-detail-wide sa-detail-actions">
                  <button type="button" className="sa-btn sa-btn-primary sa-btn-sm" disabled={saving} onClick={handleSaveIdentity}>
                    {saving ? "Salvando..." : "Salvar identificação"}
                  </button>
                  {saveError && <span className="sa-text-danger">{saveError}</span>}
                </div>
              </>
            ) : (
              <>
                <div className="sa-detail-item"><span>Hostname</span><strong>{device.hostname ?? "—"}</strong></div>
                <div className="sa-detail-item"><span>Vendor</span><strong>{device.vendor ?? "—"}</strong></div>
                <div className="sa-detail-item"><span>Modelo</span><strong>{device.model ?? "—"}</strong></div>
                <div className="sa-detail-item"><span>MAC</span><strong>{device.mac_address ?? "—"}</strong></div>
              </>
            )}
            {snmp?.cpu_load != null && (
              <div className="sa-detail-item"><span>CPU (SNMP)</span><strong>{String(snmp.cpu_load)}%</strong></div>
            )}
            {device.os_name && (
              <div className="sa-detail-item sa-detail-wide"><span>Sistema / Descrição</span><strong>{device.os_name}</strong></div>
            )}
            {wmi?.port_open && (
              <div className="sa-detail-item"><span>WMI</span><strong>{wmi.reachable ? "Conectado" : "Porta 135 aberta"}</strong></div>
            )}
          </div>
        )}

        {tab === "hardware" && (
          <div className="sa-stack">
            {hardwareLoading && !hardware ? (
              <p className="sa-empty"><span className="sa-spinner" /> Carregando hardware...</p>
