import { BaseEdge, getBezierPath, getSmoothStepPath, getStraightPath, type EdgeProps } from "@xyflow/react";

function formatBps(bps: number): string {
  if (bps >= 1_000_000_000) return `${(bps / 1_000_000_000).toFixed(1)} Gbps`;
  if (bps >= 1_000_000) return `${(bps / 1_000_000).toFixed(1)} Mbps`;
  if (bps >= 1_000) return `${(bps / 1_000).toFixed(0)} Kbps`;
  return `${Math.round(bps)} bps`;
}

function getPath(edgeStyle: string, params: Parameters<typeof getSmoothStepPath>[0]): [string, number, number] {
  if (edgeStyle === "straight") {
    const [path, lx, ly] = getStraightPath(params);
    return [path, lx, ly];
  }
  if (edgeStyle === "default") {
    const [path, lx, ly] = getBezierPath(params);
    return [path, lx, ly];
  }
  const [path, lx, ly] = getSmoothStepPath(params);
  return [path, lx, ly];
}

export default function TrafficEdge(props: EdgeProps) {
