    targetX,
    targetY,
    sourcePosition,
    targetPosition,
    data,
    markerEnd,
    selected,
  } = props;

  const edgeStyle = (data?.edgeStyle as string) || "smoothstep";
  const bpsOut = (data?.bps_out as number) ?? 0;
  const bpsIn = (data?.bps_in as number) ?? 0;
  const isActive = data?.status !== "inactive";
  const maxBps = Math.max(bpsIn, bpsOut);
  const strokeWidth = selected ? 6 : 5;
  const strokeColor = selected ? "#60a5fa" : isActive ? "#22c55e" : "#64748b";
  const duration = maxBps > 0 ? Math.max(1.2, 5 - Math.log10(maxBps + 1)) : 2.4;
  const trafficLabel = maxBps > 0 ? formatBps(maxBps) : null;

  const [edgePath, labelX, labelY] = getPath(edgeStyle, {
    sourceX,
    sourceY,
    targetX,
    targetY,
    sourcePosition,
    targetPosition,
  });

  return (
    <>
      <BaseEdge
        id={id}
        path={edgePath}
        markerEnd={markerEnd}
        interactionWidth={selected ? 20 : 6}
        style={{
          strokeWidth,
          stroke: strokeColor,
          opacity: isActive ? 1 : 0.45,
          filter: selected ? "drop-shadow(0 0 4px rgba(96,165,250,0.6))" : undefined,
        }}
      />
