import { useCallback, useRef, useState } from "react";
import type { Edge, Node } from "@xyflow/react";

interface Snapshot {
  nodes: Node[];
  edges: Edge[];
}

/** Histórico ilimitado (memória permitindo). */
export function useMapHistory(initialNodes: Node[], initialEdges: Edge[]) {
  const [nodes, setNodes] = useState<Node[]>(initialNodes);
  const [edges, setEdges] = useState<Edge[]>(initialEdges);
  const [historyVersion, setHistoryVersion] = useState(0);
  const past = useRef<Snapshot[]>([]);
  const future = useRef<Snapshot[]>([]);

  const bump = useCallback(() => setHistoryVersion((v) => v + 1), []);

  const pushHistory = useCallback(
    (currentNodes: Node[], currentEdges: Edge[]) => {
      past.current.push({
        nodes: JSON.parse(JSON.stringify(currentNodes)),
        edges: JSON.parse(JSON.stringify(currentEdges)),
      });
      future.current = [];
      bump();
    },
    [bump],
  );

  const undo = useCallback(() => {
    if (!past.current.length) return;
    const prev = past.current.pop()!;
    future.current.push({ nodes, edges });
    setNodes(prev.nodes);
    setEdges(prev.edges);
    bump();
  }, [nodes, edges, bump]);

  const redo = useCallback(() => {
    if (!future.current.length) return;
    const next = future.current.pop()!;
    past.current.push({ nodes, edges });
    setNodes(next.nodes);
    setEdges(next.edges);
    bump();
  }, [nodes, edges, bump]);

  return {
    nodes,
    edges,
    setNodes,
    setEdges,
    pushHistory,
    undo,
    redo,
    canUndo: past.current.length > 0,
    canRedo: future.current.length > 0,
    historyVersion,
  };
}

import { useCallback, useEffect, useRef, useState } from "react";
import { getToken } from "../api/client";

export interface CollabUser {
  username: string;
  color: string;
  cursor: { x: number; y: number };
}

function wsBase(): string {
  const api = import.meta.env.VITE_API_URL ?? "";
  if (api) return api.replace(/^http/, "ws");
  const proto = window.location.protocol === "https:" ? "wss:" : "ws:";
  return `${proto}//${window.location.host}`;
}

interface CollabHandlers {
  onNodeMove?: (nodeId: string, x: number, y: number, fromUser: string) => void;
  onLayoutSaved?: () => void;
}

export function useMapCollaboration(enabled: boolean, handlers: CollabHandlers = {}) {
  const [users, setUsers] = useState<CollabUser[]>([]);
  const [connected, setConnected] = useState(false);
  const wsRef = useRef<WebSocket | null>(null);
  const handlersRef = useRef(handlers);
  handlersRef.current = handlers;

  useEffect(() => {
    if (!enabled) return;
    const token = getToken();
    if (!token) return;

    const url = `${wsBase()}/ws/map?token=${encodeURIComponent(token)}&room=default`;
    const ws = new WebSocket(url);
    wsRef.current = ws;

    ws.onopen = () => setConnected(true);
    ws.onclose = () => setConnected(false);
    ws.onmessage = (ev) => {
      const data = JSON.parse(ev.data as string) as {
        type: string;
        users?: CollabUser[];
        username?: string;
        color?: string;
        x?: number;
        y?: number;
        node_id?: string;
      };
      if (data.type === "presence" && data.users) {
        setUsers(data.users);
      } else if (data.type === "cursor" && data.username) {
        setUsers((prev) =>
          prev.map((u) =>
            u.username === data.username ? { ...u, cursor: { x: data.x ?? 0, y: data.y ?? 0 } } : u,
          ),
        );
      } else if (data.type === "node_move" && data.node_id) {
        handlersRef.current.onNodeMove?.(data.node_id, data.x ?? 0, data.y ?? 0, data.username ?? "");
      } else if (data.type === "layout_saved") {
        handlersRef.current.onLayoutSaved?.();
      }
    };

    return () => {
      ws.close();
      wsRef.current = null;
    };
  }, [enabled]);

  const sendCursor = useCallback((x: number, y: number) => {
    if (wsRef.current?.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify({ type: "cursor", x, y }));
    }
  }, []);

  const sendNodeMove = useCallback((nodeId: string, x: number, y: number) => {
    if (wsRef.current?.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify({ type: "node_move", node_id: nodeId, x, y }));
    }
  }, []);

  const notifyLayoutSaved = useCallback(() => {
    if (wsRef.current?.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify({ type: "layout_saved" }));
    }
  }, []);

  return { users, connected, sendCursor, sendNodeMove, notifyLayoutSaved };
}

import { useEffect, useRef } from "react";
import { getToken } from "../api/client";

function resolveStreamBase(): string {
  const configured = import.meta.env.VITE_API_URL;
  if (configured) return configured;
  if (typeof window !== "undefined") return "";
  return "http://localhost:8000";
}

export function useMonitoringStream(onEvent?: (type: string, payload: Record<string, unknown>) => void) {
  const handlerRef = useRef(onEvent);
  handlerRef.current = onEvent;

  useEffect(() => {
    const token = getToken();
    if (!token) return;

    const base = resolveStreamBase();
    let source: EventSource | null = null;
    let closed = false;
    let retryTimer: number | undefined;

    const connect = () => {
      if (closed) return;
      source = new EventSource(`${base}/api/stream/monitoring?token=${encodeURIComponent(token)}`);
      source.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data) as { type: string; payload?: Record<string, unknown> };
          if (data.type === "reconnect") {
            source?.close();
            retryTimer = window.setTimeout(connect, 1000);
            return;
          }
          if (data.type && data.type !== "heartbeat") {
            handlerRef.current?.(data.type, data.payload ?? {});
          }
        } catch {
          /* ignore */
        }
      };
      source.onerror = () => {
        source?.close();
        if (!closed) {
          retryTimer = window.setTimeout(connect, 5000);
        }
      };
    };

    connect();

    return () => {
      closed = true;
      if (retryTimer) window.clearTimeout(retryTimer);
      source?.close();
    };
  }, []);
}

import { useCallback, useEffect, useState } from "react";

export type DashboardWidgetId =
  | "stats"
  | "status_chart"
  | "type_breakdown"
  | "discovery"
  | "devices"
  | "events";

export interface DashboardLayout {
  widgets: DashboardWidgetId[];
  hidden: DashboardWidgetId[];
}

const STORAGE_KEY = "sentinelai_dashboard_layout";

const DEFAULT_LAYOUT: DashboardLayout = {
  widgets: ["stats", "status_chart", "type_breakdown", "discovery", "devices", "events"],
  hidden: [],
};

export function useDashboardLayout() {
  const [layout, setLayout] = useState<DashboardLayout>(() => {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) return JSON.parse(raw) as DashboardLayout;
    } catch {
      /* ignore */
    }
    return DEFAULT_LAYOUT;
  });

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(layout));
  }, [layout]);

  const toggleWidget = useCallback((id: DashboardWidgetId) => {
    setLayout((prev) => {
      const hidden = new Set(prev.hidden);
      if (hidden.has(id)) hidden.delete(id);
      else hidden.add(id);
      return { ...prev, hidden: [...hidden] };
    });
  }, []);

  const moveWidget = useCallback((id: DashboardWidgetId, direction: "up" | "down") => {
    setLayout((prev) => {
      const widgets = [...prev.widgets];
      const index = widgets.indexOf(id);
      if (index < 0) return prev;
      const swap = direction === "up" ? index - 1 : index + 1;
      if (swap < 0 || swap >= widgets.length) return prev;
      [widgets[index], widgets[swap]] = [widgets[swap], widgets[index]];
      return { ...prev, widgets };
    });
  }, []);

  const resetLayout = useCallback(() => setLayout(DEFAULT_LAYOUT), []);

  const isVisible = useCallback((id: DashboardWidgetId) => !layout.hidden.includes(id), [layout.hidden]);

  return { layout, toggleWidget, moveWidget, resetLayout, isVisible };
}

