import { useCallback, useEffect, useRef, useState } from "react";
import { Bot, Send } from "lucide-react";
import { copilotChat, fetchCopilotContext } from "../api/client";

interface ChatMessage {
  role: "user" | "assistant";
  text: string;
  actions?: string[];
}

export default function NocCopilotPage() {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: "assistant", text: "Olá! Sou o NOC Copilot (DeepSeek/LLM). Pergunte sobre devices offline, alertas, anomalias ou peça um resumo operacional. Para ajuda sobre módulos do produto, use o Chatbot." },
  ]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [llmSource, setLlmSource] = useState<string | null>(null);
  const [context, setContext] = useState<Record<string, unknown> | null>(null);
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    fetchCopilotContext().then(setContext).catch(() => {});
  }, []);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const send = useCallback(async () => {
    const text = input.trim();
    if (!text || loading) return;
    setInput("");
    setMessages((m) => [...m, { role: "user", text }]);
    setLoading(true);
    try {
      const res = await copilotChat(text);
      setLlmSource(res.source ?? "rules-engine");
      setMessages((m) => [...m, { role: "assistant", text: res.answer, actions: res.suggested_actions }]);
    } catch (e) {
      setMessages((m) => [...m, { role: "assistant", text: String(e) }]);
    } finally {
      setLoading(false);
    }
  }, [input, loading]);

  return (
    <div className="sa-stack" style={{ maxWidth: 900, margin: "0 auto" }}>
      {context && (
        <div className="sa-stat-grid" style={{ gridTemplateColumns: "repeat(auto-fit, minmax(140px, 1fr))" }}>
          <div className="sa-card" style={{ padding: "1rem", textAlign: "center" }}>
            <div className="sa-text-muted">Devices</div>
            <strong>{String(context.devices_total ?? "—")}</strong>
          </div>
          <div className="sa-card" style={{ padding: "1rem", textAlign: "center" }}>
            <div className="sa-text-muted">Offline</div>
            <strong>{String(context.devices_offline ?? "—")}</strong>
          </div>
          <div className="sa-card" style={{ padding: "1rem", textAlign: "center" }}>
            <div className="sa-text-muted">Alertas pendentes</div>
            <strong>{String(context.pending_alerts ?? "—")}</strong>
          </div>
          <div className="sa-card" style={{ padding: "1rem", textAlign: "center" }}>
            <div className="sa-text-muted">Anomalias</div>
            <strong>{String(context.active_anomalies ?? "—")}</strong>
          </div>
        </div>
      )}

      <section className="sa-card" style={{ display: "flex", flexDirection: "column", minHeight: 420 }}>
        <div className="sa-card-header">
          <h3><Bot size={20} style={{ verticalAlign: "middle", marginRight: 8 }} />NOC Copilot</h3>
          {llmSource && (
            <span className="sa-text-muted" style={{ fontSize: 12 }}>
              motor: {llmSource === "rules-engine" ? "regras locais" : llmSource}
            </span>
          )}
        </div>
        <div style={{ flex: 1, overflowY: "auto", padding: "1rem", display: "flex", flexDirection: "column", gap: 12 }}>
          {messages.map((msg, i) => (
            <div
              key={i}
              style={{
                alignSelf: msg.role === "user" ? "flex-end" : "flex-start",
                maxWidth: "85%",
                padding: "10px 14px",
                borderRadius: 12,
                background: msg.role === "user" ? "var(--sa-accent, #3b82f6)" : "var(--sa-bg-muted)",
                color: msg.role === "user" ? "#fff" : "inherit",
              }}
            >
              {msg.text}
              {msg.actions && msg.actions.length > 0 && (
                <div style={{ marginTop: 8, display: "flex", flexWrap: "wrap", gap: 6 }}>
                  {msg.actions.map((a) => (
                    <span key={a} className="sa-btn sa-btn-ghost sa-btn-sm" style={{ fontSize: 11 }}>{a}</span>
                  ))}
                </div>
              )}
            </div>
          ))}
          <div ref={bottomRef} />
        </div>
        <div style={{ padding: "1rem", borderTop: "1px solid var(--sa-border)", display: "flex", gap: 8 }}>
          <input
            className="sa-input"
            style={{ flex: 1 }}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && send()}
            placeholder="Ex: quantos devices estão offline?"
            disabled={loading}
          />
          <button type="button" className="sa-btn sa-btn-primary" onClick={send} disabled={loading}>
            <Send size={16} />
          </button>
        </div>
      </section>
    </div>
  );
}

