    setAnomalies(anom);
    setJobs(jobList);
    setLoading(false);
  }, []);

  useEffect(() => {
    load().catch(() => setLoading(false));
  }, [load]);

  const anomalyColumns: Column<AnomalyRecord>[] = [
    { key: "device", header: "Device ID", render: (r) => r.device_id },
    { key: "metric", header: "Métrica", render: (r) => r.metric_name },
    { key: "severity", header: "Severidade", render: (r) => <StatusBadge status={r.severity} /> },
    { key: "message", header: "Mensagem", render: (r) => r.message },
    {
      key: "action",
      header: "",
      render: (r) =>
        !r.is_resolved ? (
          <button type="button" className="sa-btn sa-btn-ghost" onClick={() => resolveAnomaly(r.id).then(load)}>
            Resolver
          </button>
        ) : (
          "OK"
        ),
    },
  ];

  const jobColumns: Column<ReportJob>[] = [
    { key: "id", header: "ID", render: (r) => r.id },
    { key: "type", header: "Tipo", render: (r) => `${r.report_type} (${r.format})` },
    { key: "status", header: "Status", render: (r) => <StatusBadge status={r.status} /> },
    {
      key: "download",
      header: "",
      render: (r) =>
        r.status === "completed" && r.file_path ? (
          <button
            type="button"
            className="sa-btn sa-btn-secondary"
            onClick={() => {
              const name = r.file_path?.split(/[/\\]/).pop() ?? `report_${r.id}.${r.format}`;
              downloadReport(r.id, name).catch(console.error);
            }}
          >
            <Download size={14} /> Baixar
          </button>
        ) : null,
    },
  ];

  async function runReport(report_type: string, format: string) {
    setBusy(true);
    try {
      await createReportJob(report_type, format);
      await load();
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="sa-stack">
      <div className="sa-grid sa-grid-3">
        <StatCard label="Anomalias ativas" value={anomalies.filter((a) => !a.is_resolved).length} icon={Brain} />
        <StatCard label="Relatórios gerados" value={jobs.length} icon={FileText} />
        <StatCard label="IA Insights" value="7d" icon={Sparkles} />
      </div>

      <section className="sa-card">
        <div className="sa-card-header">
          <h3>Resumo executivo (IA)</h3>
          <button type="button" className="sa-btn sa-btn-secondary" onClick={() => fetchAiSummary(7).then((r) => setSummary(r.summary))}>
            Atualizar
          </button>
        </div>
        <pre className="sa-summary-text">{summary || "Carregando..."}</pre>
      </section>

      <section className="sa-card">
        <div className="sa-card-header">
          <h3>Exportar relatórios</h3>
        </div>
        <div className="sa-form-row">
          <button type="button" className="sa-btn sa-btn-primary" disabled={busy} onClick={() => runReport("devices", "xlsx")}>
            <FileSpreadsheet size={16} /> Dispositivos Excel
          </button>
          <button type="button" className="sa-btn sa-btn-primary" disabled={busy} onClick={() => runReport("events", "xlsx")}>
            <FileSpreadsheet size={16} /> Eventos Excel
          </button>
          <button type="button" className="sa-btn sa-btn-primary" disabled={busy} onClick={() => runReport("summary", "pdf")}>
            <FileText size={16} /> Resumo PDF
          </button>
          <button type="button" className="sa-btn sa-btn-secondary" disabled={busy} onClick={() => detectAnomalies().then(load)}>
            Detectar anomalias
          </button>
        </div>
      </section>

      <section className="sa-card">
        <h3>Anomalias detectadas</h3>
        <DataTable columns={anomalyColumns} data={anomalies} rowId={(a) => a.id} loading={loading} emptyMessage="Nenhuma anomalia" />
      </section>

      <section className="sa-card">
        <h3>Jobs de relatório</h3>
        <DataTable columns={jobColumns} data={jobs} rowId={(j) => j.id} loading={loading} emptyMessage="Nenhum job" />
      </section>
    </div>
  );
}

import { FormEvent, useState } from "react";
import { AlertCircle, Shield } from "lucide-react";
import { login } from "../api/client";

export default function LoginPage({ onLogin }: { onLogin: () => void }) {
  const [username, setUsername] = useState("admin");
  const [password, setPassword] = useState("admin123");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  async function handleSubmit(event: FormEvent) {
    event.preventDefault();
    setLoading(true);
    setError("");
    try {
      await login(username, password);
      onLogin();
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : "Usuário ou senha inválidos");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="sa-login-page">
      <div className="sa-login-card">
        <div className="sa-login-brand">
          <div className="sa-login-brand-icon">
            <Shield size={28} />
          </div>
          <h1>SentinelAI</h1>
          <p>Plataforma de monitoramento e inventário de rede</p>
        </div>

        <form className="sa-login-form" onSubmit={handleSubmit}>
          <label className="sa-label">
            Usuário
            <input
              className="sa-input"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              autoComplete="username"
              autoFocus
            />
          </label>
          <label className="sa-label">
            Senha
            <input
              className="sa-input"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              autoComplete="current-password"
            />
          </label>

          {error && (
            <div className="sa-alert sa-alert-error" role="alert">
              <AlertCircle size={16} />
              {error}
            </div>
          )}

          <button type="submit" className="sa-btn sa-btn-primary" disabled={loading} style={{ width: "100%" }}>
            {loading ? (
              <>
                <span className="sa-spinner" /> Entrando...
              </>
            ) : (
              "Entrar"
            )}
          </button>
        </form>
      </div>
    </div>
  );
}

import { NavigationContainer } from "@react-navigation/native";
import { createNativeStackNavigator } from "@react-navigation/native-stack";
import { StatusBar } from "expo-status-bar";
import { useEffect, useState } from "react";
import {
  ActivityIndicator,
  FlatList,
  SafeAreaView,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import Constants from "expo-constants";

const API_URL = (Constants.expoConfig?.extra as { apiUrl?: string })?.apiUrl ?? "http://localhost:8000";

type Device = {
  id: number;
  ip_address: string;
  hostname: string | null;
  status: string;
};

const Stack = createNativeStackNavigator();

function LoginScreen({ onLogin }: { onLogin: (token: string) => void }) {
  const [username, setUsername] = useState("admin");
  const [password, setPassword] = useState("admin123");
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  async function handleLogin() {
    setLoading(true);
    setError(null);
    try {
      const body = new URLSearchParams({ username, password });
      const res = await fetch(`${API_URL}/api/auth/login`, {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body,
      });
      if (!res.ok) throw new Error("Login inválido");
      const data = (await res.json()) as { access_token: string };
      onLogin(data.access_token);
    } catch (e) {
      setError(String(e));
    } finally {
      setLoading(false);
    }
  }

  return (
    <SafeAreaView style={styles.container}>
      <Text style={styles.title}>SentinelAI</Text>
      <Text style={styles.subtitle}>Monitoramento de rede</Text>
      <TextInput style={styles.input} value={username} onChangeText={setUsername} placeholder="Usuário" placeholderTextColor="#64748b" autoCapitalize="none" />
      <TextInput style={styles.input} value={password} onChangeText={setPassword} placeholder="Senha" placeholderTextColor="#64748b" secureTextEntry />
      {error && <Text style={styles.error}>{error}</Text>}
      <TouchableOpacity style={styles.button} onPress={handleLogin} disabled={loading}>
        {loading ? <ActivityIndicator color="#fff" /> : <Text style={styles.buttonText}>Entrar</Text>}
      </TouchableOpacity>
      <Text style={styles.hint}>API: {API_URL}</Text>
      <StatusBar style="light" />
    </SafeAreaView>
  );
}

async function registerPushToken(authToken: string) {
  try {
    const res = await fetch(`${API_URL}/api/mobile/push-token`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${authToken}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ token: `expo-dev-${authToken.slice(0, 16)}`, platform: "expo" }),
    });
    if (!res.ok) return;
  } catch {
    /* push opcional */
  }
}

function DashboardScreen({ token, onLogout }: { token: string; onLogout: () => void }) {
  const [devices, setDevices] = useState<Device[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    registerPushToken(token).catch(() => undefined);
    fetch(`${API_URL}/api/devices`, {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then((r) => r.json())
      .then(setDevices)
      .catch(() => setDevices([]))
      .finally(() => setLoading(false));
  }, [token]);

  return (
    <SafeAreaView style={styles.container}>
      <View style={styles.header}>
        <Text style={styles.title}>Dispositivos</Text>
        <TouchableOpacity onPress={onLogout}>
          <Text style={styles.link}>Sair</Text>
        </TouchableOpacity>
      </View>
      {loading ? (
        <ActivityIndicator color="#3b82f6" style={{ marginTop: 24 }} />
      ) : (
        <FlatList
          data={devices}
          keyExtractor={(d) => String(d.id)}
          renderItem={({ item }) => (
            <View style={styles.card}>
              <Text style={styles.cardTitle}>{item.hostname ?? item.ip_address}</Text>
              <Text style={styles.cardSub}>{item.ip_address}</Text>
              <Text style={[styles.badge, item.status === "active" ? styles.badgeOk : styles.badgeBad]}>{item.status}</Text>
            </View>
          )}
          ListEmptyComponent={<Text style={styles.hint}>Nenhum dispositivo</Text>}
        />
      )}
      <StatusBar style="light" />
    </SafeAreaView>
  );
}

function RootNavigator() {
  const [token, setToken] = useState<string | null>(null);

  return (
    <NavigationContainer>
      <Stack.Navigator screenOptions={{ headerShown: false }}>
        {!token ? (
          <Stack.Screen name="Login">{() => <LoginScreen onLogin={setToken} />}</Stack.Screen>
        ) : (
          <Stack.Screen name="Dashboard">{() => <DashboardScreen token={token} onLogout={() => setToken(null)} />}</Stack.Screen>
        )}
      </Stack.Navigator>
    </NavigationContainer>
  );
}

export default function App() {
  return <RootNavigator />;
}

