#Requires -Version 5.1
<#
.SYNOPSIS
  Grava credenciais WMI apenas no arquivo local .env (nunca no Git).

.DESCRIPTION
  - Pedido interativo (senha oculta)
  - Atualiza só WMI_* / WINRM_* no .env
  - Não imprime a senha
  - Recusa gravar se .env estiver trackeado pelo Git
#>
$ErrorActionPreference = "Stop"
$Root = Split-Path -Parent (Split-Path -Parent $MyInvocation.MyCommand.Path)
$EnvFile = Join-Path $Root ".env"

Set-Location $Root

# Segurança: .env não pode estar no índice Git
$tracked = git ls-files --error-unmatch .env 2>$null
if ($LASTEXITCODE -eq 0) {
    Write-Host "ABORTADO: .env está trackeado no Git. Remova do índice antes (git rm --cached .env)." -ForegroundColor Red
    exit 1
}

if (-not (Test-Path $EnvFile)) {
    if (Test-Path (Join-Path $Root ".env.example")) {
        Copy-Item (Join-Path $Root ".env.example") $EnvFile
        Write-Host "Criado .env a partir de .env.example"
    } else {
        New-Item -ItemType File -Path $EnvFile | Out-Null
    }
}

Write-Host ""
Write-Host "Configurar WMI (credenciais ficam só em .env local)" -ForegroundColor Cyan
Write-Host "Nao cole esta senha em chat, commit ou screenshot." -ForegroundColor Yellow
Write-Host ""

$username = Read-Host "Usuario WMI (ex.: admin ou DOMAIN\\user)"
if ([string]::IsNullOrWhiteSpace($username)) {
    Write-Host "Usuario obrigatorio." -ForegroundColor Red
    exit 1
}

$secure = Read-Host "Senha WMI" -AsSecureString
$BSTR = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure)
try {
    $password = [Runtime.InteropServices.Marshal]::PtrToStringAuto($BSTR)
} finally {
    [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($BSTR) | Out-Null
}
if ([string]::IsNullOrEmpty($password)) {
    Write-Host "Senha obrigatoria." -ForegroundColor Red
    exit 1
}

$domain = Read-Host "Dominio (opcional, Enter para vazio)"

function Set-EnvKey([string]$content, [string]$key, [string]$value) {
    $escaped = $value -replace '\\', '\\'
    # Evita quebrar linha .env com # e espaços — aspas se necessário
    if ($value -match '[\s#=''"]' -or $value -match '[^\x20-\x7E]') {
        $escaped = '"' + ($value -replace '\\', '\\' -replace '"', '\"') + '"'
    } else {
        $escaped = $value
    }
    $pattern = "(?m)^(?:#\s*)?$([regex]::Escape($key))=.*$"
    $line = "$key=$escaped"
    if ($content -match $pattern) {
        return [regex]::Replace($content, $pattern, [System.Text.RegularExpressions.MatchEvaluator]{ param($m) $line })
    }
    if ($content -notmatch "(?m)^# WMI") {
        $content = $content.TrimEnd() + "`r`n`r`n# WMI / WinRM (segredo local — nao commit)`r`n"
    }
    return $content.TrimEnd() + "`r`n$line`r`n"
}

$raw = Get-Content -Raw -Path $EnvFile
$raw = Set-EnvKey $raw "WMI_ENABLED" "true"
$raw = Set-EnvKey $raw "WMI_USERNAME" $username
$raw = Set-EnvKey $raw "WMI_PASSWORD" $password
$raw = Set-EnvKey $raw "WMI_DOMAIN" ($(if ($domain) { $domain } else { "" }))
$raw = Set-EnvKey $raw "WMI_TIMEOUT_SECONDS" "8"
# Reusa as mesmas credenciais no WinRM (Zion probes)
$raw = Set-EnvKey $raw "WINRM_USERNAME" $username
$raw = Set-EnvKey $raw "WINRM_PASSWORD" $password

# Escrita atômica
$tmp = "$EnvFile.tmp"
[System.IO.File]::WriteAllText($tmp, $raw)
Move-Item -Force $tmp $EnvFile

# Limpa senha da memória do script o máximo possível
$password = $null
[GC]::Collect()

Write-Host ""
Write-Host "OK: WMI_ENABLED=true gravado em .env (arquivo ignorado pelo Git)." -ForegroundColor Green
Write-Host "Usuario: $username" -ForegroundColor Green
Write-Host "Senha: ******** (nao exibida)" -ForegroundColor Green
if ($domain) { Write-Host "Dominio: $domain" -ForegroundColor Green }
Write-Host ""
Write-Host "Reinicie os containers para aplicar:" -ForegroundColor Cyan
Write-Host "  docker compose up -d --force-recreate api worker discovery-worker beat"
Write-Host ""
